"""Build a shareable HTML report from the verified redesign artifacts."""
import html
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
out = root / "artifacts/redesign"
results = json.loads((out / "verification-results.json").read_text())
metadata = json.loads((out / "cinematic-tour-metadata.json").read_text())
seconds = round(float(metadata["format"]["duration"]))
duration = f"{seconds // 60}:{seconds % 60:02d}"
report = out / "final-report.md"
report.write_text(report.read_text().replace("VIDEO_DETAILS", f"**{duration} · 1920×1080 · 30 fps · H.264 MP4 · zero audio tracks.** The file has streaming-friendly fast-start metadata; its SHA-256 digest and chapter timing are in the accompanying metadata."))
workflows = [
    ("Landing & responsive UI", "Pipeline interactions, live SHA-256 demo, keyboard tabs, CTAs, public routes, mobile menu, motion controls, and layouts from 320 to 1600 pixels."),
    ("Accounts & sessions", "Signup, login/logout, email verification, password recovery, single-use tokens, invalid tokens, protected routes, HttpOnly cookies, and automatic session refresh."),
    ("Projects & preferences", "Organization/project creation and rename, environment selection, switching, account appearance, and persistent notification preferences."),
    ("Runs & evidence", "Real model/search workflow, report and source links, score, saved run, confirmed steps, run integrity, Merkle proofs, content match/mismatch, filters, pagination, clipboard, and JSON downloads."),
    ("Agents & integrations", "UI identity registration, TypeScript and Python SDK logging, fingerprint match/mismatch, concurrent registrations, scoped key creation, and revocation with HTTP 401 rejection."),
    ("Alerts & team access", "Identity drift, evidence inspection, acknowledge/resolve/reopen, investigation notes, invitations and acceptance, roles, viewer restrictions, member removal, search, and invitation resend/revoke."),
]
rows = "".join(f"<tr><th>{html.escape(a)}</th><td>{html.escape(b)}</td></tr>" for a,b in workflows)
limits = "".join(f"<li>{html.escape(x)}</li>" for x in results["limits"])
scenarios = "".join(f"<li><span>PASS</span>{html.escape(r['scenario'])}</li>" for r in results["scenarios"])
css = """
.sheet:last-child{font-size:11px;line-height:1.6}.sheet:last-child p{margin-bottom:12px}.sheet:last-child h3{margin:20px 0 10px}.sheet:last-child .proof-grid img{height:140px}
@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#ede9df;font:12px/1.7 Arial,sans-serif;color:#30271d}.sheet{padding:43px 46px;min-height:297mm;page-break-after:always;position:relative;background:#fcfaf5}.sheet:last-child{page-break-after:auto}.cover{background:#21190f;color:#f5efe3}.brand{font-size:22px;font-weight:bold;letter-spacing:-1px;display:flex;justify-content:space-between;align-items:center}.brand small{font:8px monospace;letter-spacing:1px;color:#ad9c80}.eyebrow{font:9px monospace;letter-spacing:2px;color:#64863f;margin:40px 0 20px}.cover .eyebrow{color:#b3ef69}h1{font-size:54px;font-weight:400;letter-spacing:-2.5px;line-height:1.08;margin:0 0 25px}h1 em{font-family:Georgia,serif;color:#b3ef69}h2{font-size:31px;line-height:1.2;font-weight:400;letter-spacing:-1px;margin:10px 0 22px}h3{font-size:16px;font-weight:500;margin:27px 0 12px}p{margin:0 0 17px}.cover p{color:#c4b69e;max-width:530px}.hero{width:100%;margin:12px 0 28px;border:1px solid #c2f08635;border-radius:6px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:25px 0}.stat{border:1px solid #69523655;padding:18px;border-radius:5px}.stat strong{font-size:32px;letter-spacing:-1px;display:block;color:#b3ef69;line-height:1.2}.stat span{font:9px monospace;letter-spacing:.5px;color:#c4b69e}table{width:100%;border-collapse:collapse;margin:15px 0 24px;font-size:10px}th,td{text-align:left;border-bottom:1px solid #d8d0bf;padding:12px 10px;vertical-align:top}th{width:29%;font-weight:500;color:#3c5c27}td{color:#665845}.note{background:#edf2e2;border-left:3px solid #769b42;padding:17px;font-size:10px;margin:22px 0}.footer{position:absolute;bottom:25px;left:46px;right:46px;display:flex;justify-content:space-between;font:8px monospace;letter-spacing:.5px;color:#8c7b61;border-top:1px solid #bda88340;padding-top:12px}.proof-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.proof-grid img{width:100%;height:180px;object-fit:cover;object-position:center 65%;border:1px solid #d6cebd;border-radius:4px}.proof-grid p{font:9px monospace;color:#796e5d;margin-top:8px}.mono{font:9px/1.8 monospace;overflow-wrap:anywhere;background:#f0ece1;padding:15px}ul{padding-left:18px;font-size:11px}li{margin-bottom:7px}a{color:#477331}.scenario-list{list-style:none;padding:0;margin:20px 0;display:grid;gap:3px}.scenario-list li{display:flex;align-items:flex-start;gap:12px;border-bottom:1px solid #ddd5c5;padding:3px 0;font-size:8.5px;line-height:1.4;margin:0}.scenario-list span{font:8px monospace;color:#477331;flex-shrink:0;padding-top:1px}.small{font-size:10px;color:#796b55}.two{columns:2;column-gap:25px}.two p{break-inside:avoid}
"""
footer = lambda n: f'<footer class="footer"><span>TRUSTCHAIN / EVIDENCE IN FOCUS</span><span>14 NOVEMBER 2026 · {n:02d}</span></footer>'
content = f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>TrustChain — Redesign report</title><style>{css}</style><body>
<section class="sheet cover"><div class="brand">trustchain.<small>DESIGN + VERIFICATION REPORT</small></div><div class="eyebrow">ESPRESSO / WARM WHITE / GREEN</div><h1>Intelligence,<br>with a <em>proof.</em></h1><p>A complete visual redesign of the landing page, account experience, and multi-page evidence workspace. Cinematic motion, consistent controls, and verified product workflows.</p><img class="hero" src="screenshots/landing-desktop.png" alt="Redesigned landing page"><div class="stats"><div class="stat"><strong>30/30</strong><span>BROWSER SCENARIOS</span></div><div class="stat"><strong>20 + 7</strong><span>UNIT / REGRESSION TESTS</span></div><div class="stat"><strong>{duration}</strong><span>SILENT · 1080P · 30 FPS</span></div></div><p class="small">Production build, TypeScript, ESLint, and whitespace checks passed. Latest applicable scenario results; detailed execution history follows.</p>{footer(1)}</section>
<section class="sheet"><div class="brand">trustchain.<small>FUNCTIONAL VERIFICATION</small></div><div class="eyebrow">01 / THE PRODUCT STILL WORKS</div><h2>Real workflows.<br>Recorded evidence.</h2><p>Chromium against the production frontend, real FastAPI, PostgreSQL, Redis, model/search providers, both MCP servers, and Anvil chain 31337 with the evidence workers and watchdog.</p><table>{rows}</table><div class="note"><strong>Execution history:</strong> the consolidated production run passed 28/29. A source-link omission was corrected, and the affected complete pipeline passed its focused rerun. One supplemental controls scenario passed. The latest result is 30 unique passing scenarios, with no skipped scenarios counted as passes.</div><h3>A confirmed research run</h3><p class="small">Run <strong>run_20261114_120724_cc77ccd2</strong> completed with a 2,128-character cited report and a score of 85/100. All 10 steps were confirmed. Run integrity, proof retrieval, and reopening the saved report passed.</p><div class="mono">Proof step 94 · block 96 · chain 31337<br>0xb33702d2a5b35619d87e7bc0bdff7ce59a1b336c874b6e457bd57444fcbfb15d</div>{footer(2)}</section>
<section class="sheet"><div class="brand">trustchain.<small>SCENARIO REGISTER</small></div><div class="eyebrow">02 / WHAT WAS ACTUALLY TESTED</div><h2>30 scenarios.<br>Latest results: passed.</h2><ol class="scenario-list">{scenarios}</ol>{footer(3)}</section>
<section class="sheet"><div class="brand">trustchain.<small>IMPLEMENTATION + DELIVERY</small></div><div class="eyebrow">03 / THE FINISHED EXPERIENCE</div><h2>One coherent system.<br>From first visit to final proof.</h2><p>The design spans the landing page, authentication and recovery, invitation acceptance, all 12 workspace areas and run details, pricing, coming-soon, and error screens. Dark mode is the default; the warm light theme remains available.</p><p>Motion includes the dimensional evidence object, orbital paths, scroll reveals, page entrances, charts, dialogs, and hover states. Persistent motion controls and system reduced-motion preferences keep the experience adaptable.</p><h3>A report defect corrected during verification</h3><p>Original search URLs now travel separately through the pipeline state, so model summaries cannot silently drop them from the final sources. The report distinguishes durable recording from confirmed on-chain anchoring, and no longer hardcodes an incorrect network claim. Seven regressions verify the source/report behavior.</p><div class="proof-grid"><div><img src="screenshots/live-run-verification.png" alt="Real successful run verification"><p>LIVE / RUN INTEGRITY</p></div><div><img src="screenshots/live-step-proof.png" alt="Real confirmed Merkle proof"><p>LIVE / CONFIRMED STEP PROOF</p></div></div><h3>The silent cinematic film</h3><p>{duration} · 1920×1080 · H.264 · 30 fps · zero audio tracks. Real application actions with animated chapter labels, cursor, click ripples, field-note cards, and reading/progress indicators. The disposable key is masked and revoked. The supplied reference is preserved.</p><h3>Limits of this result</h3><ul>{limits}</ul><p class="small">The complete written report, structured test summary, screenshots, chapter timings, video metadata, and reproduction instructions are included beside this document. The test chain bootstrap addresses were refreshed from the actual local deployment receipt; production infrastructure was not modified.</p>{footer(4)}</section>
</body></html>'''
(out/'final-report.html').write_text(content)
print('Built final-report.html and finalized video details in final-report.md')
